window.VD=window.VD||{};window.VD["audi/q2-ga"]={"q2-ga-120-km-h-overrun-warning":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose: </strong>To activate or deactivate a message reminding you that you are exceeding the 120km/h speed limit.  </p>\n<p><strong>Procedure: </strong><br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.  </p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:  </strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.  </p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.  </p>\n<p><strong>5</strong> – Select byte<strong>“0”</strong> <br/>Then check to enable or uncheck to disable the box in<strong>“6”</strong>:<strong>“Speed warning at 120 kph (75 mph) active</strong>“.  </p>","q2-ga-acc-distance-setting-in-mmi":"<p><strong>Purpose</strong>: for convenient adjustment of ACC distance setting via MMI.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong> <br/><br/><br/> 3 – Click on ” <strong>Select</strong> ” and then click on “Select”.<strong><strong>13 – Regul Dist.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>14117</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><strong>“Distance basic setting</strong>” or <em>“Distanzgrundeinstellung</em>”<br/><br/> 7 – Set value to<strong> 1</strong> to activate.<br/><br/></p>\n<ul>\n<li>After activation, press the “car” button in the MMI, select the driving assistance zone – “adaptive cruise control” tab.</li>\n<li>Here you can now specify the respective distance setting under “Distance”:<br/><br/>Distance 1 – large distance, i.e. early braking by the ACC distance system<br/>Distance 2 – small distance, i.e. normal to early braking by the ACC distance system<br/>Distance 3 – small distance, i.e. normal to late braking by the ACC distance system<br/>Distance 4 – smallest distance, i.e. late braking by the ACC distance system; if a vehicle stops in front of you on the freeway and cuts you off, the system will not react as abruptly if there is still enough distance.</li>\n</ul>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7452-7b2530cd.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7166-a399eb74.webp\"/></figure>","q2-ga-activate-a-second-phone-via-bluetooth":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to connect two phones simultaneously via Bluetooth to the MMI if you don’t have the Audi Phone Box option. <br/><br/><br/><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Vehicle configuration – Support_second_phone</strong></strong>”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<p><em>Restart MMI</em></p>","q2-ga-activate-auto-school-mode":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Adds a driving-school mode view to the MMI, displaying turn signals, speed, etc. (also ideal for accompanied driving).  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule function list CAN-Driving_school</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Vehicule menu operation-menu_display_driving_school_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","q2-ga-activate-daytime-running-lights-drl-only-in-auto-position":"<p><strong>Purpose:</strong> Enables daytime running lights (DRL) only when the headlight control switch is in the “auto” position.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Daytime running lights—Daytime running lights only in the AUTO position</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_drl_auto_switch-c7669352.webp\"/></figure>","q2-ga-activate-g-meter":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: Adds the G-Meter (Accelerometer) to the Virtual Cockpit screen.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Display Acceleration</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/accelerationdisplay-4bb736e5.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/audi_a3_8v_power_torque-169cb34b.webp\"/></figure>","q2-ga-activate-gearshift-recommendation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Activates the gearshift recommendation. The gearshift recommendation is then displayed in the lower section of the ODB.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>“<br/>Then check Bit<strong>“5</strong>“.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/check_aiguille-9b803756.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7102-675f485c.webp\"/></figure>","q2-ga-activate-heated-mirrors-retrofit":"<p><strong>Purpose:</strong> to activate heated/defrosting mirrors after retrofitting. <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“42-Driver door</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“.</p>\n<p><strong>5 </strong>– Select byte <strong>04 </strong>and uncheck bit <strong>0</strong> <em>“Heated Mirrors NOT installed”</em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8K0-959-793-B_Module42_Byte4-a964f232.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>“.</p>\n<p><strong>5 –</strong> Select byte <strong>04</strong> Uncheck bit <strong>0</strong> <em>“Heated Mirrors NOT installed”</em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8K0-959-793-B_Module42_Byte4-a964f232.webp\"/></figure>","q2-ga-activate-hidden-mmi-menu":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: Enables the hidden menu of the MMI MIB2 High Scale (Hidden Menu / Green Menu / Engineering Menu). </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on ” <strong>Select”</strong>, then click on ” <strong>Select</strong> “, then click on ” <strong>Select</strong> “. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<strong><strong>5F – Information Electr.</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Choose ” <em><strong>Developer test mode</strong> “</em> or <em>” <strong>Developer mode</strong> “</em> and then activate.</p>\n<p><em>No need to restart the MMI.</em></p>\n<p><em>To open the hidden menu with NAV/MAP (or CAR) and RADIO. First press and hold NAV/MAP (or CAR), then press RADIO and wait 5 seconds. </em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/A4-Hidden-Menu-ec3628a6.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/A4-Hidden-Menu2-0030a834.webp\"/></figure>\n<p><strong><a href=\"#/t/access-the-audi-red-engineering-menu\">–&gt; To access the Audi Red Engineering menu</a></strong></p>","q2-ga-activate-intruder-alarm-with-horn":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate an alarm with horn in the event of intrusion into the vehicle, and to lock the vehicle if the door is opened.  </p>\n<p><strong>Warning! There are 8 lines of coding to do here. </strong></p>\n<p><em><strong>For vehicles without original alarm! </strong></em><br/><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Additional functions – Signalhorn ohne KL 15</strong>”.</p>\n<p><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_disable_horn-34a976ae.webp\"/></figure>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – Akustischer Alarm Signalhorn</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – Alarmsignal</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“frequency modulated</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – DWA Alarmverzoegerung</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“driver door contact thatcham</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Anti-theft protection – DWA Camper Modus</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>\n<p><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Protection antivol – Sirenen Alarmzahl</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“10 alarms</strong>” and confirm.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Protection antivol – Verzoegerung Panikalarm</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“2 sekunden verzoegerung</strong>” and confirm.</p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Anti-theft Alarm System</strong></strong>”<strong> Anti-theft Alarm System</strong><br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","q2-ga-activate-lane-assist-memory-function":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to store the Lane Assist function in memory. If you deactivate it, the Lane Assist will not automatically resume the next time you start up.  <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1 (For Camera A5 5Q0 / 3Q0) :</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Personalization of lane dept. warning Cl.  15 on</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“last setting </strong>” and confirm.</p>\n<hr/>\n<p><strong>Line 1 (For Camera A5 2Q0):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>”.</p>","q2-ga-activate-reversing-camera-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the rearview camera after it has been installed on the MMI (Low or High camera retrofit). <br/><br/><br/><strong>Procedure:</strong> <br/><strong>1</strong> – With the engine off and the ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic port.<br/><br/><strong>2</strong> – Turn on the ignition, then launch the VCDS program.</p>\n<hr/>\n<h4><strong>Low Camera (Standard)</strong></h4>\n<p><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>6</strong> – Select byte <strong>19</strong><br/>. Then set bit <strong>4</strong> to “Rear View Camera (RVC) Low installed (PR-KA1).”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/C25A41FA-66F7-4FC9-B7F4-1761395A1D01-1024x483-11bbd3cf.webp\"/></figure>\n<p><strong>Line 2 (Optional, if parking assist is available)</strong> <strong>:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte <strong>02</strong><br/>. Then, for bits <strong>4-5</strong>, select<em> “10 Camera Type: Rear View Camera (RVC) installed.”</em></p>\n<p><strong>Hardware upgrade :</strong></p>\n<p>The camera’s video cable is connected to the infotainment control unit. It is installed in the glovebox.   <br/><br/>The 2 pins of the reversing camera are used in the 12-pin quadlock (blue). Usable cable set: Part no. 000 979 009 E <br/><br/>Quadblock Assignment :<br/><br/>Pin 6 = video line<br/>Pin 12 = shielding</p>\n<hr/>\n<h4>High-Resolution Camera</h4>\n<p>Enabling the High-Resolution Rearview Camera (dynamic guide lines, various display modes).</p>\n<p><strong>Line 1:</strong><br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>“.<br/><br/> 4 – Select <strong>“Installation List”</strong><br/><br/> 5 – Tick:<strong>“6C – Rear View Camera</strong>” in the list</p>\n<p><strong>6</strong> – Save coding</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>6C – Rear view camera</strong>.”<br/><br/><strong></strong> 5 – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – <strong>Coding</strong>: 02 72 06 01 02 00 20 01 40 00 40</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>6</strong> – Select byte <strong>19</strong><br/>. Then clear bit <strong>4</strong>.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Car Function List BAP Gen2 – VPS_0x0B</strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose the<strong>“active</strong>” value.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong><strong>Car Function List BAP Gen2 – VPS_0x0B_msg_bus</strong></strong></strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but further down<br/>.<br/>From this menu, select the value “<strong><strong>Comfort data bus</strong></strong>“</p>\n<p><strong>Line 6</strong> <strong>:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte <strong>02</strong><br/>. Then, for bits <strong>4-5</strong>, select<em> “10 Camera Type: Rear View Camera (RVC) installed.”</em></p>","q2-ga-activate-trailer-coupling-retrofit":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the installation of a retrofit trailer hitch (trailer/towbar retrofit).  </p>\n<p><em>Caution! The configuration in the control unit for motor 01 is not supported for certain models. In this case, the coding can be skipped. Control units that are not installed can also be skipped. Please note that certain coding steps must be performed based on the part numbers of the installed components (camera).      </em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Capture-decran-2024-01-09-215831-4f89678c.webp\"/></figure>\n<p><strong>Warning!! Depending on the modules you have installed, there are up to 12 coding lines to complete here; most ECUs require a long coding process with a “trailer” that must be enabled!  </strong><br/><br/><strong>Proceed :</strong><br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Select <strong>“Installation List”</strong><br/><br/><strong>5</strong> – Check the box next to “<strong>69 – Trailer</strong>” in the list</p>\n<p><strong>6</strong> – Save coding</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailergateway-3cb3c873.webp\"/></figure>\n<p><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“01 – Motor</strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>05</strong>“<br/>. Then check bit “<strong>4</strong>“: “<strong>Trailer installed</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailermoteur-fdaad0ca.webp\"/></figure>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>“09 – Cent. Elect.”</strong></strong>“.</p>\n<p><em>For power plants <strong>with</strong> coding:</em><br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>,” then click on “<strong>Long Coding Helper</strong>“<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then, in the “<strong>Bit 0-7</strong>” drop-down menu, select “<strong>01 Trailer Connector Diagnosis active</strong>“.</p>\n<p><strong><em>Or</em></strong> Byte<strong>“01</strong>” check <strong>Bit 1</strong><strong>“Trailer Hitch Control Module Installed</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailercentrelec-0a9e9b3c.webp\"/></figure>\n<p><em>For power plants <strong>without </strong>coding :</em></p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Networking trailer connection device</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“built in”</strong> and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“24990</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“trailer stabilization</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>Active</strong>” and then confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter code<strong>“71679</strong>” (optional code)<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-1</strong> “01 Trailer Hitch installed (manually removable)”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerpark-212dd6b1.webp\"/></figure>\n<p><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 – Auto Dist. Reg. </strong>“.<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>14117</strong>” or “<strong>20103</strong>“<br/><br/><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“<br/><br/><strong>6</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“03</strong>” (camera 2Q0/3Q0)<br/>Then check Bit<strong> 3</strong> “Trailer Recognition Control Module installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailerdist-da789d91.webp\"/></figure>\n<p><br/><br/><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>34 – Correct. Assiet. </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select the “<strong>00</strong>” byte<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><br/><strong>Line 8:</strong></p>\n<p><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>3C – Lane Change</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“02</strong>” (camera 5Q0) or<strong>“00</strong>” (camera 2Q0/3Q0)<br/>Then check Bit <strong>4-7</strong> “10 or 20 ECU for draw bar, with ECU for draw bar”.<br/><br/><br/><br/><strong>Line 9:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>6C – Rearview Camera</strong>.”<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>04</strong>“<br/>Then set bit <strong>0</strong> (“equipment_ahk, installed”)<br/><br/><br/><strong>Line 10:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>6D – Trunk Electrical System </strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>01</strong>“<br/>Then set bit <strong>7</strong> (“trailer, 0 = not installed / 1 = installed”)<br/><br/><strong>Line 11:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Front, Sensors, Driver Assistance   </strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.</p>\n<p><strong>5</strong> – Click ” <strong>Encoding – 07</strong>,” then click “<strong>Long Coding Helper</strong>“</p>\n<p><strong>6</strong> – <em>Choose the line according to your camera reference!</em></p>\n<p>Select byte<strong>“16</strong>” (Camera 5Q0)</p>\n<p>Then check bit <strong>0-7</strong> “01 trailer_control_module, installed”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailera5-685c17e4.webp\"/></figure>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“11</strong>” (Camera 3Q0)</p>\n<p>Then set bit<strong> 0 ( </strong>“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“05</strong>” (Camera 2Q0)</p>\n<p>Then set bit <strong>4</strong> (“AAG, 0 = not_coded / 1 = coded”)</p>\n<p><strong>Line 12:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong><strong>69 – Trailer</strong></strong>“.<br/><br/><strong>4</strong> – Click on ” <strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“01</strong>”<br/>Then check Bit <strong>0-3</strong> “01 Diagnosis of the line to the socket, active”.</p>\n<p>Select byte<strong>“03</strong>”<br/>Then check Bit<strong> 0-3</strong> “01 Terminal 30 output (pin 9 socket), activated”.</p>\n<p><em><strong>OR</strong></em></p>\n<p>Select byte<strong>“04</strong>”<br/>Then check Bit<strong> 0-7</strong> “02 Terminal 30 output switched (pin 10) Trailer connected”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/trailer69-acbfa990.webp\"/></figure>","q2-ga-activate-window-operation-with-ignition-off":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables the windows to be operated (up/down) with the ignition off and the door open.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Access control 2—Disable FH follow-up for Class 15.</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>active</strong>,” then confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Access control 2—Cancel FH access follow-up when door opens</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>not</strong> <strong>active</strong>,” then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vitrecontactcoupevagcoding-1024x530-1c73d125.webp\"/></figure>","q2-ga-activate-wiper-replacement-position-menu-on-mmi":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Activates the position for wiper blade replacement, so that it can be controlled from the MMI menu. After activation, the wipers move to the service position.   </p>\n<p><em><strong>Tip</strong> for wiper replacement position without menu: switch off the ignition and hold the wiper lever in the lowest position until the wipers are in the blade replacement/maintenance position.</em> <br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/wipers-5da2a6fb.webp\"/></figure>\n<p><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Windshield wiper-Menuesteuerung Frontwischer”</strong> / <strong>“Frontscheibenwischer-Menuesteuerung Frontwischer”.</strong><br/><br/><strong>7</strong> – On the same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, select<strong>“Active</strong>” and confirm.</p>","q2-ga-activate-deactivate-daytime-running-lights-drl-via-mmi":"<p><strong>Purpose:</strong> to activate/deactivate the daytime running lights (DRL) from the MMI.  </p>\n<p>ATTENTION to your country’s regulations and technical inspection for daytime running lights!<br/>However, if you’re coding in your car to avoid using too much of your battery, this is a good solution…  </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Activation possible via BAP or control sequence</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_jour_drl-0a93900d.webp\"/></figure>","q2-ga-activation-of-progressive-interior-lighting":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> turns interior lights (door knobs, dashboard, center console) on and off gradually. By default, interior lights are switched on and off immediately with the headlights. Activating this function will cause a slow fade effect each time the interior lights are switched on or off. (Interior Light Fade in/out)     <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Interior lighting-KL58 Einschalten mit Rampe</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/kl58rampe-e361a4ce.webp\"/></figure>\n<p>OBDeleven:</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/KL58rampeOBDeleven-1fdea7c1.webp\"/></figure>","q2-ga-adjust-soundaktor-volume":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to adjust/deactivate the volume of the Soundaktor (speaker built into the windscreen bay to simulate a false engine noise). If you hear a squeaking or buzzing sound, or don’t like the noise, deactivate it completely. (Soundaktuator)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A9- Struct. Sound terminal</strong>“.</p>\n<p><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/> 5 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Volume of structure-borne noise actuator</strong>”<br/><br/> 6 – Adapt the value accordingly <br/>Default value: 100% <br/>If the value is set to 0, the sound amplifier is completely disabled.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_6985-1024x629-a592b6b9.webp\"/></figure>","q2-ga-automatic-door-unlocking-with-dsg-in-p-position":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Automatically unlocks all doors when the DSG automatic transmission is shifted to the “P” position.  </p>\n<p><strong>Procedure: </strong><br/><strong>1 –</strong> Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2 –</strong> Switch on the ignition and run the VCDS program.</p>\n<p><strong>3 –</strong> Click on <strong>“Select”</strong>, then click on <strong>“09 – Cent. Elect.”</strong>.</p>\n<p><strong>4 –</strong> Click <strong>“Security Access – 16,”</strong> then enter the code <strong>“31347”</strong></p>\n<p><strong>5 –</strong> Click on <strong>“Adaptation – 10”</strong>.</p>\n<p><strong>6 –</strong> At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“Access control – Autounlock NAR”</strong></p>\n<p><strong>7 –</strong> On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select <strong>“active</strong>, <strong>“</strong> then confirm.</p>","q2-ga-automatic-folding-of-mirrors":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Automatically folds mirrors when vehicle is locked. <br/><br/><br/><em>The vehicle must be equipped with the “Electrically folding mirrors (with comodo in door)” option. </em><br/><br/><br/><strong>Warning! There are 5 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>4</strong>“<br/>. Then check bit “<strong>6</strong>“: “<strong>Comfort Mirror Folding active</strong>“<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>42 – Driver’s Door</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>4</strong>“<br/>. Then check bit “<strong>6</strong>“: “<strong>Comfort Mirror Folding active</strong>“<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Funk Spiegelanklappen</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Menuesteuerung Funk Spiegel anklappen</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.<br/><br/><em><br/>!!! For folding mirrors without having to hold down the remote control button </em><br/><br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Funk Spiegelanklappung Modus</strong>“.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“by look command via remote control key</strong>” and confirm.</p>","q2-ga-automatic-window-closure-in-the-event-of-rain":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Automatically closes the windows and sunroof when it rains.  <br/><br/><br/><strong>Warning!! There are 4 lines of code to write here.   </strong><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>ZV KOMFORT</strong> <strong>– Regenschliessen_ein_aus</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_rain_closing_v4--bda80ebf.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong><strong>ZV KOMFORT</strong></strong><strong>– Regenschliessen_art</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select “<strong>Permanent</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_rain_closing_v3-149ffc8c.webp\"/></figure>\n<p><strong>Line 3:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong><strong>ZV KOMFORT</strong></strong><strong>– Menu Control: Close When It Rains</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_rain_closing_v2--1d335d5e.webp\"/></figure>\n<p><strong>Line 4:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.</p>\n<p><strong>5</strong> – Click “<strong>Coding – 07</strong>.”</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>RLFS</strong>“</p>\n<p><strong>7</strong> – Select byte “<strong>0</strong>“<br/>Then check bit “<strong>1</strong>“: “<strong>Rain Light Function active</strong>“<br/>Then check bit “<strong>2</strong>“: “<strong>Rain Closing active</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rls2-74324943.webp\"/></figure>\n<p>–&gt; If RLFS is inaccessible with VCDS, you must use OBDeleven:  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/OBDelevenRLFS-628x1024-ef35951a.webp\"/></figure>\n<p>Restart MMI</p>\n<ul>\n<li>The RLHS sensor is not compatible!</li>\n</ul>\n<ul>\n<li>If the feature is enabled: Automatic window closing when it rains:</li>\n</ul>\n<p>With the Audi Q2, you have the option of activating the automatic window closing function in the event of rain in the on-board network control unit.</p>\n<p>The windows and panoramic roof are linked to the rain sensor, so the doors close automatically. The operating mode can be activated or deactivated in the CAR menu on the entertainment information system (MMI). </p>","q2-ga-brake-disc-drying":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to adjust the intensity of brake disc drying. If your car has a tendency to squeal when parked in wet weather, for example, the annoying drying of the disc brakes can be reduced or even completely deactivated, so that there are no scratches or squeaks.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03- Electronic brakes</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“40304</strong>“.</p>\n<p><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>“.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“brake disc drying</strong>“<br/><br/> 7 – On this same page, there is a second drop-down menu but towards the bottom<br/>of the page.<br/>On this, choose the value accordingly to your choice: ” <strong>not activated, low, medium, high</strong> ” then validate.</p>\n<p>Factory setting: <strong>low</strong> &lt;- recommended</p>","q2-ga-change-odb-language":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to choose the language of your on-board computer. For an A3 8V imported from abroad, for example.   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Variante linguistique</strong>” /<strong>“Language Version</strong>“.<br/><br/><strong>7</strong> – Select language from second value list</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/886F4702-2DBC-4C30-8716-D4D05CCE1338-da4cd84c.webp\"/></figure>","q2-ga-comfort-flashing-light":"<p><strong>Purpose:</strong> to set the number of flashes for the “Comfort flashing” option.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Turn signal control-Komfortblinken Blinkzyklen</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose between<strong>“3</strong>” and<strong>“5</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_clignotant_confo-f1a2f919.webp\"/></figure>\n<p><em>Information: If, after coding, the number of flashes has not changed, on your MIB screen Menu -&gt; Settings -&gt; Factory settings -&gt; Lighting (Your interior lighting configurations will also be reset).</em></p>","q2-ga-coming-home-automatic":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Automatically activates the Coming Home function (no need to make a headlight call).  <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Comfort Illumination—Coming Home Status</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“automatic</strong>” and confirm.</p>","q2-ga-coming-home-on-opening-the-drivers-door":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Starts Coming Home when the driver’s door is opened, not when the ignition key is removed.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Comfort illumination-Coming Home Einschaltereignis</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Driver door</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_coming_home_driv-a8ce4f84.webp\"/></figure>","q2-ga-compass-display-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to display a compass on the ODB (on-board computer), if you have GPS navigation (NAV), and to change its position on the speedo.</p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.<br/></p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>“<br/>Then check Bit<strong>“6</strong>“.</p>\n<p><strong>Line 2 (if line 1 unavailable) :</strong></p>\n<p><strong>3 –</strong> Click on ” <strong>Select”</strong>, then click on ” <strong>17- Instruments</strong> “.</p>\n<p><strong>4 –</strong> Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 –</strong> On this page, at the very top, there is a drop-down menu. In this drop-down menu, select the ” <strong>Navigation /</strong><strong>Compass</strong>” channel.</p>\n<p><strong>6 –</strong> In the ” <strong>Value:</strong> ” option, select<strong>“Enabled</strong>“.  </p>\n<p><strong>Line 3 (to change the compass position on the ODB) :</strong></p>\n<p><strong>3 –</strong> Click on ” <strong>Select”</strong>, then click on ” <strong>17- Instruments</strong> “.</p>\n<p><strong>4 –</strong> Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5 –</strong> On this page, at the very top, there is a drop-down menu. From this drop-down menu, select the “<strong>Compass</strong> <strong>indicator</strong> ” channel.</p>\n<p><strong>6 –</strong> In the ” <strong>Value:</strong> ” option, select the desired value for the compass position on the ODB (default: lower position).</p>\n<figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/compassbas-b76d2a41.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/compasshaut-cbdd1575.webp\"/></figure>\n</figure>","q2-ga-complete-opening-of-sunroof-with-remote-control":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows the sunroof to open fully when opening with the remote control.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control 2-SAD Richtung Komfortoeffnen</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Open”</strong> and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_sliding_roof-a62f2b37.webp\"/></figure>","q2-ga-correction-of-odb-consumption-display":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: Allows you to correct the fuel consumption display on the On-Board Computer / Virtual Cockpit.  </p>\n<p><em>Note: The changes you make affect the display of instantaneous fuel consumption, average fuel consumption, and fuel quantity.</em> </p>\n<p><strong>Procedure:</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong></strong> 2 – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “ <strong>Select</strong>,” then click <strong> “17 – Instruments.”</strong></p>\n<p><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”</p>\n<p><strong>5</strong> – Select the <strong>Channel:</strong> <em>“Display correction of <em>consumption and operating range</em>“</em></p>\n<p><em>Set the consumption correction factor between 85% and 115%</em> <em>(base value: 100)</em></p>\n<p><em>Example 1: Calculation based on volume per distance (e.g., l/100 km): Target: 9.3 l/100 km. Actual: 9.8 l/100 km. (100, 9.8 / 9.73 ? 105.38) Channel 3 will be changed from 100 to 105.<br/>Example 2: Calculation based on distance per volume (e.g., MPG): Target: 23 MPG. Actual: 24 MPG. (100, 23/24, and 95.83) Channel 3 will be changed from 100 to 96       </em>.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/consomqb-7270c66a.webp\"/></figure>\n<p><em>Example 3: The fuel consumption reported by the ODB is 5.9 L/100 km; after testing, it is actually 6.3 L/100 km.<br/>Calculation of the rate to be entered: (6.3 * 100) / 5.9 = 106.78. The rate used will be 107%; the fuel consumption figure reported by the ODB will be approximately 0.1 L/100 km too low. </em></p>\n<p>Consumption is immediately modified on the MMI.</p>","q2-ga-daytime-running-light-deactivation-drl-using-the-handbrake":"<p><strong>Purpose:</strong> to deactivate the daytime running lights (DRL) using the handbrake.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Daytime running lights-Tagfahrlicht Dauerfahrlicht bei Handbremse abschalten</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-5G---Desactiver-les-feux-de-jours-DRL-avec--6d661897.webp\"/></figure>","q2-ga-deactivate-audio-reduction-for-parking-assistance":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to disable the volume reduction when reverse gear is engaged or when the parking assist system is manually activated.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>10 – Parking Assistance</strong>.”</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select <strong>“Audio Attenuation Request</strong> <strong>” </strong>/ <strong>“Demande réduction audio” </strong>/ <strong>“Anforderung Audioabsenkung” </strong>from the drop-down list</p>\n<p><strong>7</strong> – Select ” <strong>Off”</strong> in the second value list  <br/></p>","q2-ga-deactivate-brake-pad-warning-light":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the worn brake pad warning light on the ODB (on-board computer), e.g. if the brake pad has no sensor or if the sensor has a problem / Brake Pad Warning light desactivation. (For Phase 1)   </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>4</strong></p>\n<p>Disable bit <strong>7</strong> <strong>” </strong><strong>Brake Pad Wear Sensor installed “</strong></p>\n<p><em>Restart the vehicle so that the warning light is no longer displayed.</em></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/brakepadsensormqb-d9823960.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant-frein-d4619ec9.gif\"/></figure>","q2-ga-deactivate-horn-without-ignition":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to turn the horn on or off when the ignition is off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Additional Functions – Signalhorn ohne KL 15</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select “<strong>not active</strong>” to disable it or <strong>“active”</strong> to enable it, then click “Submit.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_disable_horn-34a976ae.webp\"/></figure>","q2-ga-deactivate-open-door-alarm-with-contact":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the alarm which is triggered when the door is opened and the contact is in position P.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on “<strong>Select”</strong>, then click on “<strong>17- Instruments”</strong>.</p>\n<p><strong>4</strong> – Click on <strong>“Adaptation –</strong> 10”</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Ignition active message</strong>” / ”  <strong>Message ignition active. trigger </strong>  “<br/><br/><strong>6</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“tbd</strong>” /<strong>“No</strong> <strong>display</strong>” / “<strong>Aucun affichage</strong>” then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_ignition_active_-e1e03128.webp\"/></figure>","q2-ga-deactivate-rear-fog-light-warning":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the warning message on the dashboard, which will remind you to turn on the rear fog lights when you reach the set speed.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rearfogwarningvagcoding-1fb1b8b9.webp\"/></figure>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong> <strong>Aussenlicht_Heck-Nebelschlusslicht Warngeschwindigkeit</strong></strong>”<br/><br/><strong>7</strong> – On this same page, there is a second menu at the bottom<br/>of the page.<br/>On this menu, choose a value in KM/H (warning display speed) then validate.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/rearfogwarningvagcoding2-1024x673-9e9c0ae9.webp\"/></figure>","q2-ga-deactivate-right-hand-overtaking-prevention":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the ACC lane assist system, e.g. when on the freeway and there is a traffic jam in the left lane, the vehicle starts to slow down.  </p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>13 –  <strong>Auto Dist. Reg</strong></strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte<strong>“02</strong>”<br/>Then uncheck Bit<strong>“5</strong>”: “<strong><strong>overtaking_right_prevention</strong></strong>”</p>\n<p>OBDeleven: Select <strong>“overtaking_right_prevention”</strong><br/>Change from “activated” to “Deactivated”.</p>","q2-ga-deactivate-switch-on-low-beam-message":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Disables the warning message or dialog prompting the driver to turn on the low beams when the headlight switch is in position 0.  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement1-1024x609-756a4f05.webp\"/></figure>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Außenlicht_uebergreifend-Fahrlichtwarnung_Hinweis_Konfig</strong>” / ” <strong>driving light_hint_config</strong> ”  <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom of the page.<br/>From this menu, select “<strong>kein_Hinweis</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/allumerfeuxdecroisement2-f3950d1b.webp\"/></figure>","q2-ga-deactivate-activate-electric-handbrake-for-rear-brake-pad-change":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate/activate the electric handbrake in maintenance mode in order to change/replace the rear brake pad/disc linings. (Lining change mode)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/>To begin, set the gear lever to P and remove the electric handbrake on the button. Check that there are no faults/errors before starting basic setup.<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start trim change mode.</strong>”<br/><br/><strong>6</strong> – Click on<strong>“Go</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/plaquettearriere-1024x629-2b32f223.webp\"/></figure>\n<p><br/><br/>A fault message will appear on your ODB indicating “<strong>Parking brake fault</strong>”, but this is normal and should be ignored<br/><br/> 7 – Wait for<strong>“Procedure complete</strong>” to be displayed<br/><br/> 8 – Once finished, return to the program until it closes<br/><br/> 9 – Switch off the vehicle’s ignition, then disconnect the VAG-COM cable<br/><br/><strong>10</strong> – <strong>Change the linings on both sides!</strong><br/><br/><br/></p>\n<p><strong>To reactivate the electric handbrake :</strong><br/><br/><br/><strong>11</strong> – With engine off and ignition switched off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>12</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>13</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brake</strong>”.<br/><br/><strong>14</strong> – Click on<strong>“Basic setting – 04</strong>”.<br/><br/><strong>15</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“End trim change mode.</strong>”<br/><br/><strong>16</strong> – Click on<strong>“Go</strong>”.<br/><br/><strong>17</strong> – Wait for<strong>“Procedure complete</strong>” display</p>","q2-ga-deactivation-of-audi-parking-system-engagement-beep":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> deactivates the beep when the Audi Parking System is engaged.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click “ <strong>Select</strong>,” then click “ <strong>10 – Parking Assistance</strong>.”</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“</p>\n<p><strong>5</strong> – Click on ” <strong>Adaptation – 10</strong> “.</p>\n<p><strong>6</strong> – Select ” <strong>Tonalité d’activation de l’aide au stationnement </strong>” / ” <strong>Park assist activation</strong> <strong>tone </strong>” / ” <strong>Aktivierungston für Einparkhilfe </strong>” from value list</p>\n<p><strong>7</strong> – Select ” <strong>Off”</strong> in the second value list  <br/></p>","q2-ga-disable-am-frequency-on-the-mmi":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to deactivate the MMI’s AM radio frequency (AM radio frequency is rarely used, unlike FM radio frequency).  </p>\n<p><br/><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong> </p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.</p>\n<p><strong>4</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>6</strong> – Select Byte <strong>14</strong></p>\n<p>Set bit <strong>1</strong> <strong>“AM_disable </strong> </p>\n<figure>\n</figure>","q2-ga-disable-the-safelock-feature":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to disable the SafeLock feature, displaying the warning message “Check SAFELOCK! Owner’s manual!” on the ODB after the ignition is turned off. The vehicle can be unlocked from the inside even after it has been locked from the outside.   </p>\n<p><br/><em>Safelock is an anti-theft system that prevents thieves from gaining access to the car. This device locks the doors—both from the outside and the inside—when the driver activates the central locking remote control after leaving the vehicle.<br/>If occupants are still inside, they cannot open the doors or even lower the windows. The car can then become a veritable trap.  </em></p>\n<p><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong> “.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong> “.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong> <strong>ZV allgemein – ZV_ohne_Safe_Funktion</strong></strong>”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“installed</strong>” and confirm.</p>\n<figure>\n<figure><img alt=\"safelock\" decoding=\"async\" loading=\"lazy\" src=\"img/safelock-860e326f.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/safelock2-3b72ec8c.webp\"/></figure>\n</figure>","q2-ga-door-lock-unlock-confirmation-beep-horn":"<p><strong>Purpose:</strong> to set confirmation of door locking/unlocking with beep (alarm) or horn.  <br/><br/><br/><strong>Warning!! There are 5 lines of code to write here—actually, 6. </strong> <em>(After programming, if it doesn’t work, enable the option on your screen in CAR – Open/Close Settings – check “Audible Confirmation”)</em> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Unlock acoustic feedback</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Acknowledgement signals—Lock Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>of the page.<br/>From this menu, select “<strong>Yes</strong>” and then confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals-Akustische Rueckmeldung global</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Menuesteuerung Akustische Rückmeldung</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Duration of the acoustic feedback from the single horn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose<strong>“normal</strong>” or<strong>“kurz</strong>” (for a short signal), then confirm.<br/><br/><strong><br/>!!! If your vehicle is not equipped with an alarm, here is the code you need to change to activate the horn </strong>  :<br/><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Acknowledgement signals—Akustische Rückmeldung Signalhorn</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","q2-ga-electronic-differential-lock-xds":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to set the electronic differential lock (XDS)  <br/><br/>The Electronic Differential Lock (XDS) is an extension of the familiar EDS function.<br/>XDS does not react to acceleration slip, however, but rather unloads the inside front wheel when cornering.<br/>XDS applies pressure to the inside wheel during cornering from the hydraulic ESP to prevent slippage.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“03 – ABS brakes</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Expanded electronic differential lock</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but towards the bottom<br/>of the page.<br/>On this, choose the value according to your preference:<br/>–<strong>“Standard</strong>” (default XDS)<br/>–<strong>“Weak</strong>” (weak XDS)<br/>–<strong>“Medium</strong>” (medium XDS)<br/>–<strong>“Strong</strong>” (strong XDS)<br/>then validate.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Activer-blocage-electronique-du-differentie-72fe63e4.webp\"/></figure>","q2-ga-enable-cd-dvd-extraction":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> activates the function for copying multimedia data (music, films, etc.), similar to the SD card function. Allows you to import / copy / load all compatible CD/DVD data onto the MMI hard disk.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Copy multimedia data-Optical drive</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“On”</strong> and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/cdcopymib-6336f5eb.webp\"/></figure>","q2-ga-flash-mode-lights-during-emergency-braking":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: Enables the turn signals to flash during an emergency stop.  </p>\n<p>Proceed : <br/>1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket. <br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Aussenlicht_Blinker – Emergency alert blinken</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>","q2-ga-fold-down-mirrors-with-ignition-on":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Enables automatic folding of mirrors when the ignition is switched on, rather than when the vehicle is locked.  <br/><br/><br/><em>The vehicle must be equipped with the “Electrically folding mirrors (with comodo in door)” option, and the coded option in the tuto must automatically fold the mirrors.  </em><br/><em>Caution: Does not work properly with vehicle equipped with KESSY option</em>.  <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Mirror adjustment /</strong><strong>spiegelverstellung-Signalisierung_Spiegelanklappung</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“inactive</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7297-1024x746-ed161cb7.webp\"/></figure>","q2-ga-headlamp-washer-settings-xenon":"<p><strong>Purpose:</strong> to manage the number of manual activations before the headlamp washer is activated on Xenon / to set the delay time before the headlamp washer comes out / the duration of the headlamp washer jet on Xenon.  <br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong><strong>Line 1 (number of activations before headlamp washer):</strong></strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Windshield wiper-Anzahl Betaetigungen Frontwaschanlage pro SRA Aktivierung</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, choose a value of your choice (default value<strong>“5</strong>”) then validate.</p>\n<p><em>Other settings for headlamp washer in drop-down menu :  </em></p>\n<ul>\n<li>“<strong>Windshield wiper – SRA verzoegerungszeit</strong>” (delay time before the windshield wiper comes out)</li>\n</ul>\n<ul>\n<li>“<strong>Windshield wiper – SRA waschzeit</strong>” (headlamp washer duration, default value 700ms)</li>\n</ul>","q2-ga-hill-start-assist":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to set Hill Start Assist operation. (hill-start assist)   <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“03 – ABS</strong><strong>Brakes </strong>”.<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Hill Start assistant</strong>” / “Assistant démarrage en côte”.<br/><br/><strong>6 – </strong> On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value based on your preference:</p>\n<ul>\n<li>“<strong>normal</strong>” (default value)</li>\n<li>“<strong>Early</strong>” (faster triggering)</li>\n<li>“<strong>Late”</strong> triggering</li>\n</ul>\n<p>then click “Submit.”</p>","q2-ga-increase-distance-between-curb-and-car-park-assist":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to set the distance between the kerb and the car during Audi Park Assist.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Park/Steer Assist</strong>” / <strong>“10 – Parking Assist”</strong><br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“Abstand zum Bordstein” / ” </strong><strong>Distance to curb</strong>” / <strong>“Distance from the curb”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>of the page.<br/>From this menu, select the distance of your choice (in cm). The default value is “<strong>15 cm</strong>“; then click “Confirm.” </p>","q2-ga-increase-gas-pedal-sensitivity":"<p><strong>Purpose:</strong> to increase accelerator pedal sensitivity. (better acceleration response with S Tronic, more significant than with manual).  <br/><br/>Proceed : <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong> <br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assistance</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>“.  </p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Commutation profil de conduite</strong>” /<strong>“Driving profile switchover</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this, choose the value: “<strong><em>directly: controlled by threshold value</em></strong>” / “<em><strong>Direct controlled over threshold value</strong></em>” then confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7198-330b03e4.webp\"/></figure>","q2-ga-interior-lighting-off-when-trunk-is-opened":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> deactivates interior lighting when only the trunk is opened.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong> “.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong> “.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Interior lighting Innenlicht-bei offenem Heckdeckel einschalten</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“inactive</strong>” and confirm.</p>","q2-ga-key-operation-with-ignition-on":"<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to use the key and lock the vehicle with the ignition switched on or the engine running. (Very practical with a Keyless Kessy key)  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control-Funk bei Klemme 15 ein</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“active</strong>” and confirm.</p>","q2-ga-keyless-go-automatic-keyless-entry":"<p><strong>Purpose:</strong> automatically locks the vehicle when you leave it with the key, provided KEYLESS Go (keyless entry/locking and starting system) is installed. Unfortunately, the folding function of the outside mirrors is not controlled and may have to be performed manually with the key if necessary.   </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>2</strong>“<br/>Then check bit “<strong>4</strong>“<br/></p>","q2-ga-lane-assist-activation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate Lane Assist for vehicles with Sign Assist and/or Light Assist options.  </p>\n<p>The vehicle must be equipped with the <strong>3Q0</strong> or <strong>2Q0</strong> camera (different A5 coding, the camera is located at the top of the windshield, level with the rearview mirror, in the shape of a triangle).  <br/><br/><br/><strong>Watch out! There are 12 lines (3Q0) or 16 lines (2Q0) of coding to do here.</strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/></p>\n<h3><strong>For module A5 for camera 3Q0 :</strong><br/></h3>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“16</strong>”<br/>Then check Bit<strong> 7</strong><strong>“Lane departure warning system (HCA) active / installed [PR-7Y9]</strong>”.</p>\n<p><em>Or</em> byte <strong>00</strong>,bit <strong>0</strong><br/><br/><strong>Line 2 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-on state of lane departure warning</strong>” /<strong>“HCA_On_State</strong>”.<br/><br/><strong>7</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Menu</strong>” and confirm.</p>\n<p><strong>Line 3 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“HCA_Warning_Intensity</strong>”.<br/><br/><strong>7</strong> – On this same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“Menu</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“BAP_Personalisierung</strong>” / <strong>BAP_Personalization</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not activated</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Intervention Moment</strong>”/<strong>“Point_of_intervention</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Late</strong> or <strong>Menu</strong>” and confirm.</p>\n<p><strong>OR</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“14</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“Point_of_intervention, setting_via_menu</strong>”.<br/><br/><br/><strong>Line 6 (if available):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong>Personalization of lane dept. warning Cl.  15 on</strong>“<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“last setting </strong>” and confirm.</p>\n<p><strong>FIN A5 3Q0</strong></p>\n<h3><strong>For A5 module for camera 2Q0 :</strong></h3>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“08</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“A0 Point_of_intervention, late_setting_over_menu</strong>”.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 0-1</strong><strong>“03 Configuration_for_lane_departure_warning_Kl15, Last_setting</strong>”.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 2-3</strong><strong>“0C Lane_assist_system_mode, Selection_over_menu</strong>”.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“09</strong>”<br/>Then check Bit<strong> 7</strong><strong>“HC, 0 = not_coded / 1 = coded</strong>”.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 0</strong><strong>“Hc_messages, 0 = not_coded / 1 = coded</strong>”.</p>\n<p><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 1-3</strong><strong>“02 HC_Warn_Intensity Set, Setting_over_Menu</strong>”.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“17</strong>”<br/>Then check Bit<strong> 5-7</strong><strong>“20 Hc_variant, Variant_1” or “00 Hc_variant, Variant_0</strong>”.</p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-on status of lane departure warning system</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“on (setting via menu) </strong>” ” then confirm.</p>\n<p><strong>FIN A5 2Q0</strong></p>\n<p><br/><strong>Continued coding for all 3Q0 and 2Q0 cameras:</strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-LDW_HCA_0x19</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6-</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-LDW_HCA_0x19_msg_bus</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“data Extended</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Lane_Departure_Warning</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_Lane_Departure_Warning_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“4</strong>”<br/>Then check Bit<strong>“6</strong>”:<strong>“Lane Maintenance Assist installed</strong>”.<br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“11</strong>”<br/>Then check Bit<strong>“1</strong>”:<strong>“Lane Maintenance Assist information (BAP) installed/active</strong>”.</p>\n<p><strong>Line 7:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assist</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“3</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Lane Assist installed</strong>”.</p>\n<p><em>Or</em> byte <strong>0</strong>, bit <strong>4</strong> <em>or</em> byte <strong>4</strong>, bit <strong>0</strong></p>\n<p><strong>Line 8:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“10 – Assistance Stationt</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“71679</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“3</strong>”<br/>Then check Bit<strong>“5</strong>”:<strong>“Lane departure warning with steering assistance installed</strong>”.</p>","q2-ga-lane-assist-settings":"<p><strong>Purpose</strong>: Adjusts lane departure warning, driver inactivity deactivation threshold, steering assist intensity and steering wheel vibration intensity.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<h4><strong>Adjusting the driver inactivity deactivation threshold</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Deactivation threshold for lane departure warning Driver inactivity</em>” or <em>“Deaktivierungsschwelle Fahrerinaktivität”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– early (deactivates Lane Assist within 7 seconds)<br/>– medium (factory setting, deactivates Lane Assist within 7 to 10 seconds)<br/>– late (deactivates Lane Assist within 11 to 15 seconds)</p>\n<h4><strong>Adjust the intensity of the steering assist</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em> <em>“Lane Departure Warning Intensity Steering Assistance”</em> or <em>“Intensität Lenkradunterstützung”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting range:<br/><br/>– low (Lane Assist switches off earlier depending on ambient conditions, as less/more sensitive steering interventions are carried out)<br/>– medium (factory setting)<br/>– high (Lane Assist switches off later depending on ambient conditions, as more/more intensive steering interventions are carried out)</p>\n<h4><strong>Adjust steering wheel vibration intensity</strong>:</h4>\n<p><strong>3</strong> – Click on ” <strong>Select”</strong>, then click on “Select”.<strong><strong>A5 – Front Camera</strong></strong>” .</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>20103</strong>”</p>\n<p><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>6 </strong>– Select Channel <em>:</em><em>“Steering wheel vibration intensity</em>” or <em>“Intensität Lenkradvibration”.</em><br/></p>\n<p>Adjust value accordingly<br/>Setting value range:<br/><br/>– low<br/>– medium (factory setting)<br/>– high</p>","q2-ga-lap-timer":"<p><strong>Purpose:</strong> to add the stopwatch to the ODB/Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“3</strong>”:<strong>“Lap Timer active</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","q2-ga-license-plate-illumination-open-trunk":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> turns on license plate illumination when trunk / tailgate is open.  <br/><br/><br/><strong>Warning! There are 3 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Leuchte 25KZL HA59</strong></strong> – <strong> Lichtfunktion C 25</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this, choose the value<strong>“Heckdeckel Offen</strong>” and confirm. <em>(origin : nicht aktiv)</em><br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose “<strong><strong>Leuchte 25KZL HA59</strong></strong> – <strong> Dimmwert CD 25</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“100</strong>” and confirm. <em>(origin : 0)</em></p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte25KZL HA59 – Dimming Direction CD 25</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but towards the bottom<br/>of the page.<br/>On the latter, choose<strong>“maximise</strong>” then validate.</p>","q2-ga-light-assist-activation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the high beam assistant for vehicles with Sign Assist and/or Lane Assist options.  <br/></p>\n<p>The vehicle must be equipped with a <strong>3Q0</strong> camera (the camera is located at the top of the windshield, level with the rearview mirror, in the shape of a triangle).   <br/><br/><br/><strong>Watch out! There are 4 lines of coding to do here.</strong></p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Menu control high-beam assistant</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“present</strong>” and confirm.<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Menu control high-beam assistant factory setting</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“present</strong>” and confirm.</p>\n<p><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Fernlicht_Assistent-Extended_Fernlichtsteuerung</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, choose<strong> “AFS: FLA: BCM high beam” </strong>or<strong> “AFS: FLA: high beam over AFS</strong>”, then confirm.<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Wizard</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“21</strong>”<br/>Then, in the<strong>“Bit 5-7</strong>” drop-down menu, select<strong>“20 AFS_coding_Light_Assist, High_Beam_Assist</strong>”.</p>","q2-ga-light-assist-always-active":"<p><strong>Purpose:</strong> automatically activates the high beam assistant on start-up if it was active before the ignition was switched off.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Assistance light functions-Fernlichtassistent Reset</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“not active</strong>” and confirm.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/fernlicht-6b04f01d.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/lightassist-1a9a5499.webp\"/></figure>","q2-ga-lock-mmi-cd-dvd-eject-button":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: to lock/unlock the CD/DVD eject button on the MMI.  </p>\n<p><em>Protection against CD theft.  </em></p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition, then run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/> 3 – Click on “<strong>Select”</strong>, then click on<strong>“5F – Information Electr.</strong>”. <strong>Procedure:</strong> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>4</strong> – Click on “<strong>Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – Select <strong><em>“eject lock</em></strong> / <strong><em>“Auswurfssperre</em></strong><em> </em>/ <strong><em>“CD Eject Button </em></strong>then set the value to <strong>Active</strong> <em>for Eject Lock.</em></p>\n<p>To eject the CD/DVD, set the value to <strong>Off</strong> for normal use of the button.</p>","q2-ga-lower-passenger-mirror-when-reversing":"<p><strong>Purpose:</strong> Automatically lowers the passenger-side rearview mirror when reversing. </p>\n<p>The mirror adjustment button must be in the “<strong>R</strong>” position for the passenger-side mirror to lower automatically. </p>\n<p><strong>Warning! There are 2 lines of coding to do here. </strong> </p>\n<p><strong>Procedure:</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“52 – Passenger door</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.</p>\n<p><strong>5</strong> – Select byte “<strong>4</strong>“<br/>Then check bit “<strong>2</strong>“: “<strong>Reserve Gear Mirror Dipping active</strong>“<br/>and bit “<strong>3</strong>“: “<strong>Position Memory for Reserve Gear Mirror Dipping active</strong>“</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-7-Abaisser-le-retroviseur-passager-lors-de-la-9710a97c.webp\"/></figure>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.</p>\n<p><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>31347</strong>.”</p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Access Control 2-Spieglelabsenkung bei Rueckwaertsfahrt</strong>“</p>\n<p><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_abaisser_retro-3ad889c2.webp\"/></figure>","q2-ga-memory-for-heated-seats":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>How it works :</strong> When you switch on the heated seat(s), as soon as you remove the key from the ignition the setting is immediately switched off. With this activation, when you switch the ignition back on, the seat will have returned to the level at which you left it.  </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose  </p>\n<p>“<strong>Retention of driver’s seat heater level</strong>” for <strong>Driver’s seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_dr-51646659.webp\"/></figure>\n<p>and/or<strong>“Retention of passenger’s seat heater level</strong>” for <strong>Passenger seat heater memory</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/3AA-907-044-AG_Module08_Adaptation_retention_of_pa-61b11e06.webp\"/></figure>\n<p><br/><br/><strong>6</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“active</strong>” and confirm.</p>","q2-ga-microphone-sensitivity-adjustment":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to adjust the intensity of the hands-free system’s microphone.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Microphone sensitivity</strong>” or “<strong>Mikrofonempfindlichtkeit</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose a value expressed in<strong>“dB</strong>” (default value<strong>“0 dB</strong>”) then validate.<br/></p>","q2-ga-mirror-folding-adjustment-with-remote-control":"<p><strong>Purpose:</strong> Allows you to set the option to fold the side mirrors using the remote control when locking the vehicle. <br/><br/><br/><em>The vehicle must be equipped with the “Power-folding side mirrors” option</em> <em>!</em><br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<em><br/></em><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access Control 2-Funk Spiegelanklappung Modus</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>From this menu, select the value that suits your needs, then confirm.</p>\n<ul>\n<li>Default: <strong>“by convenience operation via remote control key”</strong> = press and hold the button on the key fob to fold the outside mirrors.</li>\n<li>Alternative: <strong>“by look command via remote control key”</strong> “by looking command via the remote control key” = briefly press the button on the key fob to fold the side mirrors.</li>\n</ul>","q2-ga-modify-power-steering-hardness":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to adjust the hardness of the power steering for a softer steering wheel (Comfort) or a harder sporty one (Dynamic). <br/>Warning: if you have the driving mode selection, do not modify! <br/><br/><strong>Procedure </strong>: <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program. Procedure: 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>Line 1:</strong> <br/><br/> 3 – Click on<strong>“Select”</strong>, then click on<strong>“44 – Steering Assistance</strong>“.</p>\n<p><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“19249</strong>“.  </p>\n<p><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>“.<br/><br/> 6 – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Courbes caractéristiques d’assistance de direction</strong>” /<strong>“Characteristic curve of steering assistance</strong>“<br/><br/> 7 – On this same page, there is a second drop-down menu but towards the bottom<br/>of the page.<br/>On this, choose the value:<strong>“Confort</strong>” or <strong>“Dynamic”</strong> then validate.</p>\n<p>selection_by_charisma: You have the driving modes, do not modify this value otherwise you will lose the hardness of the steering wheel according to your driving mode!  </p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/steeringassistance-1024x506-c5ba8daa.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/assistancedirection-scaled-eed591de.webp\"/></figure>","q2-ga-modify-warning-thresholds-for-icy-conditions":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to select the outside temperature value for the risk of icy conditions for which the warning is displayed on the dashboard (Ice Warning).  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Outsitde temperature p ice warning entry temperature</strong>” for the value at which the alert sounds to warn of frost. (Origin: 4°C)<br/>Then choose<strong>“Outsitde temperature p ice warning exit temperature</strong>” for the value at which the frost alert ends. (Origin: 6°C)  </p>\n<p><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom of the page.<br/>On this menu, choose the temperature value you want.</p>","q2-ga-motor-start-button-pulse":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the heartbeat when the Start Engine Stop button is pressed for the keyless start option.  </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZAT_illumination_concept_mybeat_clamp58xt</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7456-0f43b3a6.webp\"/></figure>\n<p><strong>Line 2:</strong> <br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>05 – Access/Start Authorization</strong>.”<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“ZAT_illumination_modus_mybeat_clamp58xt</strong>”.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7457-aa96d69a.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_7455-26181335.webp\"/></figure>","q2-ga-needle-check":"<p><strong>Purpose:</strong> to activate the scanning of the speedometer needles when the car is started. (Works with Virtual Cockpit) (Needle Sweep)  <br/><br/><br/><strong>Proceed :</strong><br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>5</strong> – Select byte<strong>“1</strong>”<br/>Then check Bit<strong>“0</strong>”:<strong>“Gauge Test/Needle Sweep (Stading) active</strong>”.<br/></p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/GOLF-7-VAGCOM---CHECK-DES-AIGUILLES-1-dab4b41b.webp\"/></figure>","q2-ga-oil-temperature-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to display oil temperature on the ODB/Virtual Cockpit.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>” .<br/><br/><strong>5</strong> – Select byte<strong>“10</strong>”<br/>Then check Bit<strong>“1</strong>”:<strong>“Display Oil Temperature</strong>”.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/temperature-huile-vagcoding-ef203ab4.webp\"/></figure>","q2-ga-opening-closing-windows-with-kessy":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate closing and opening of windows and sunroof with the KESSY keyless entry system,<strong> </strong>keep pressing the handle until the windows are fully closed or open.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control 2-Kessy Komfort oeffnen</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Access control 2-Kessy Komfort schliessen</strong>“.<br/><br/><strong>7</strong> – On the same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“Active</strong>” and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/ouverture-fermeture-kessy-mqb-scaled-2d844473.webp\"/></figure>","q2-ga-panel-display-on-odb-virtual-cockpit":"<p><strong>Purpose:</strong> displays speed limit signs on the ODB/Virtual Cockpit (Sign Assist)   <br/><br/><br/>Vehicle must be equipped with <strong>3Q0</strong> camera <br/><br/><br/><strong>Warning! There are 9 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-traffic_sign_recognition_0x21</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_List_BAP_Gen2-traffic_sign_recognition_0x21_msg_bus</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, select<strong>“data Extended</strong>” and confirm.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_road_sign_identification</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong> then click on<strong>“5F – Electr. information</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6 –</strong> On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Car_Function_Adaptations_Gen2-menu_display_road_sign_identification_over_threshold_high</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.<br/><br/><strong>Line 5:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong><strong>5F – Information Electr.</strong></strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“24</strong>”<br/>Select Bit <strong>6</strong><br/><br/><strong>Line 6:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“16</strong>”<br/>Then, in the Bit <strong>4</strong> drop-down menu, select<strong>“Traffic sign recognition (VZE) active [PR-QR9]</strong>”.<br/><br/><strong>Line 7<strong> (Optional)</strong>:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Display end of speed limit symbol</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“activated</strong>” and confirm.</p>\n<p><strong>Line 8:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select</strong>” then click on “.<strong>A5 – Frt Sens. Drv.  Assist</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Road Sign Detection Fusion Mode</strong>” /<strong>“Détection des panneaux de signalisation mode fusion</strong>”.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose<strong>“Traffic sign detection</strong>” to use camera recognition only, or<strong>“Traffic sign fusion</strong>” for camera + gps speed, then confirm.<br/><br/><strong>Line 9:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Coding – 07</strong>” then click on<strong>“Long Coding Helper</strong>”.<br/><br/><strong>6</strong> – Select byte<strong>“5</strong>”<br/>Then check Bit<strong>“2</strong>”:<strong>“Traffic Sign Recognition installed</strong>”.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/panneauaudi-8a53d2c3.webp\"/></figure>","q2-ga-rear-lights-activated-with-daytime-running-lights-drl":"<p><strong>Purpose:</strong> Enables the rear lights to turn on when the daytime running lights (Scandinavian DRL) are activated (This method turns on the instrument panel lights) <br/><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>In this drop-down menu, select “<strong>Daytime running lights—Tagfahrlicht—Dauerfahrlicht activated in addition to parking lights</strong>.”<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu near the bottom of the page.<br/>From this menu, select “<strong>active</strong>” and then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/5Q0-937-084-Q_Module09_Adaptation_feux_arriere_drl-eff83f7a.webp\"/></figure>","q2-ga-make-up-quantity-displayed-on-odb":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Displays the amount of fuel needed to completely fill your tank on the ODB / Virtual Cockpit. <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>“.<br/><br/><strong>4</strong> – Click on<strong>“Coding – 07</strong>“, then on<strong>“Long Coding Helper</strong>“.<br/><br/><strong>5</strong> – Select byte “<strong>10</strong>“<br/>. Then check bit “<strong>4</strong>“: “Volume to Be Replenished”</p>\n<p>If it’s a hidden bit, you need to replace the <strong>0</strong> with a <strong>1</strong> in “<strong>Binary</strong>.”</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/Golf-MKVII-Affichage-quantite-carburant-ODB-1024x3-6098b6ed.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/refuel-quantity-golf7-504de88f.webp\"/></figure>","q2-ga-reprogramming-a-new-battery":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to reprogram or recode all data for the new battery after it has been replaced. <br/><br/><br/><strong>Watch out! There are 4 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click ” <strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Nominal Battery Capacity</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>From this menu, select the rated capacity listed on your battery. For example: “<strong>70Ah</strong>“<br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Technology</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down<br/>.<br/>From this menu, select the corresponding value<br/>. For example: For the VARTA E39, select “<strong>Etoffe</strong>” / “<strong>Fleece</strong>” for AGM.<br/><br/><strong>Line 3:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Adaptation—Battery Manufacturer</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu further down the page<br/>.<br/>From this menu, select the corresponding brand:<br/>For example: For the VARTA E39, select “<strong>VAO</strong>.”<br/><br/><strong>Line 4:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>19 – CAN Gateway</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Adaptation – 10</strong>.”<br/><br/><strong>5</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select “<strong>Battery Configuration—Battery Serial Number</strong>.”<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu toward the bottom<br/>.<br/>In this menu, enter the corresponding serial number:<br/>Note: Enter only the <strong>last 10 digits</strong> of the serial number.<br/><br/></p>\n<hr/>\n<p><strong>Battery Status Detection Features:</strong></p>\n<p><br/>The battery status detection in the battery data module calculates the following values, which are transmitted via the LIN bus to the J533 diagnostic data bus interface:<br/>1 “battery not present” detection: if the battery data module does not detect a battery for<br/>more than 30 seconds, a corresponding bit is set to 1<br/>2 voltage that temporarily allows for optimal battery charging<br/>3 “engine start capability” bit. It indicates whether the battery is currently capable of starting<br/>the engine or not<br/>4. The amount of charge that can still be temporarily drawn from the battery before reaching the limit of<br/>its ability to start the engine<br/>5. The battery’s current state of charge<br/>6. Battery aging. Battery aging can be determined using parameters such a<br/>, including the battery’s energy storage capacity and instantaneous power output.<br/>7 battery open-circuit voltage<br/>8 battery internal resistance  </p>\n<p><strong>The battery sensor in the J367 battery monitoring control unit:</strong></p>\n<p>Knowing whether the battery has enough electrical energy to restart the engine is essential for the start-stop system to function properly.<br/>The control module is located directly on the “negative” terminal of the ground wire and is connected to the diagnostic interface via the LIN data bus.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/charge-batterie-c76863ff.webp\"/></figure>\n<p><strong>Signal Usage:</strong><br/>The battery sensor records the following values:<br/>– Battery temperature<br/>– Battery voltage<br/>– Charging current<br/>The battery temperature is calculated using a lookup table and the ambient temperature.<br/>It also allows for estimates of the battery’s charging time.<br/>Using the data obtained in this way, it is possible to adjust the charging control—particularly the charging voltage—to the battery’s state of charge and operating conditions. The goal is to increase the availability of the start-stop system by optimally utilizing data from the starter battery. </p>\n<p><strong>Consequences in the Event of a Malfunction</strong><br/>If the battery sensor is defective, the battery status can no longer be detected correctly.<br/>A fault is logged in the diagnostic interface’s fault memory. The start-stop system is deactivated. </p>\n<p><strong>Battery</strong></p>\n<p>The vehicle’s battery is housed in the engine compartment and protected by a battery tray. The size and type of battery depend on the engine version, equipment, and country-specific variant. Standard batteries, EFB batteries, and AGM batteries are used.<br/>Vehicles with gasoline engines and start/stop systems are equipped with an EFB battery, while vehicles with diesel engines and start/stop systems are equipped with an AGM battery. Vehicles with auxiliary heaters typically have an AGM battery.   </p>\n<p><strong>EFB</strong></p>\n<p>An EFB battery (short for Enhanced Flooded Battery) is a reinforced flooded battery. The positive plate inside the battery is coated with an additional layer of polyester mesh. This provides the battery’s active material with additional support on the plate. These batteries have greater resistance to charge-discharge cycles than standard batteries. During charging, an EFB battery is treated like a standard battery.    </p>\n<p><strong>AGM Battery</strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-agm-f4b81a74.webp\"/></figure>\n<p>In AGM (Absorbent Glass Mat) batteries, the battery electrolyte is retained within a microporous glass mat. An AGM battery is characterized not only by even greater resistance to charge-discharge cycles compared to an EFB battery, but also by its leak-proof design. When charging, follow the charger’s user manual and, if applicable, select the AGM battery program.  </p>\n<p>In the case of AGM batteries, the automotive battery electrolyte is retained within a microporous glass mat. In addition to<br/>increased resistance to charge-discharge cycles, an AGM battery is characterized by its high level of leak resistance. Sealing is of crucial<br/>importance, particularly when the battery is installed in<br/>the passenger compartment. When charging, follow the charger’s user manual and, if necessary, select the program for<br/>AGM batteries.   </p>\n<p>Below, we can see the brand, serial number, and manufacturer of the battery</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/batterie-124711ff.webp\"/></figure>","q2-ga-seat-heater-reduction-time-setting":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to set the value in minutes of the heating reduction time for heated seats. As a general rule, Audi vehicles reduce the heat output of level 3 seat heating to level 2 after 10 minutes. It is also possible to activate the return from level 2 to level 1.    </p>\n<p><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>” then click on<strong>“08 – Climatronic</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Time until seat heating reduction level 3 to level 2</strong>” /<strong>“Zeit bis Sitzheizleistungsrücknahme Stufe 3 auf Stufe 2</strong>” (also for 2 to 1).</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, choose the value in minutes (0 = function disabled) then validate.</p>","q2-ga-set-acc-control-in-1-km-h-increments":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose</strong>: to adjust the ACC distance setting from the factory setting so that it can be set in 1 km/h increments by pressing the switch.  <br/></p>\n<p>By default, the PLUS and MINUS buttons on the adaptive cruise control system adjust your speed in 10 km/h increments. You can change the coding in 1 km/h increments by briefly pressing the button. And use the old 10 km/h speed increments by pressing and holding the buttons.  </p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/> 2 – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><br/> 3 – Click on ” <strong>Select</strong> ” and then click on “Select”. <strong><strong>13 – Regul Dist.</strong></strong> “.</p>\n<p><strong>4</strong> – Click on “<strong>Security Access – 16</strong>” then enter the code “<strong>14117 <em>or</em></strong> <strong>20103</strong>”.</p>\n<p><strong>5</strong> – Click on “<strong>Coding – 07</strong>”.</p>\n<p><strong>6</strong> – Click on “<strong>Long Coding Helper</strong>” .</p>\n<p><strong>7</strong> – Select Byte <strong>02</strong></p>\n<p>Select bit <strong>6</strong> “Operation Mode 2”.</p>\n<p>Some speed controller modules may use a different coding or even have this parameter as an adaptation instead of the coding. Make sure that the option you are about to modify is correctly labeled.</p>\n<p>Module 13 → Adaptation → Mode de fonctionnement / Operation Mode → Mode de fonctionnement 2 / Operation Mode 2</p>","q2-ga-speed-of-radar-or-reversing-camera-deactivation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Selects the speed at which the radar and/or reversing camera are deactivated.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click “<strong>Select</strong>,” then click “<strong>10 – Parking Assistance</strong>.”<br/><br/><strong>4</strong> – Click “<strong>Security Access – 16</strong>,” then enter the code “<strong>71679</strong>“<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Switch-off speed for parking assist</strong>“.<br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“15</strong>” km/h, depending on your preference.</p>","q2-ga-speed-threshold-settings-for-cornering-light-activation":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> Allows you to adjust the speed thresholds for turning the corner lights on and off via the fog lights. (Corner Lights)   <br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> </p>\n<p><br/><strong>Proceed :</strong> <br/><strong>1 </strong>– Engine off, ignition off, connect your official VAG-COM VCDS cable to<br/>the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2 </strong>– Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1 (Turn Signal Activation Speed):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“statisches Kurvenlicht-Untere Geschwindigkeitsschwelle.”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>In this menu, adjust the value accordingly and then confirm. (Default value: 0 km/h) </p>\n<p><em>Note: When this value is specified, the turn signals are turned off when the vehicle is stationary and are activated only once the corresponding set speed is reached.</em> <br/><br/><strong>Line 2 (Turn Signal Fade-Out Speed):</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on “<strong>Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – At the very top of this page, there is a drop-down menu.<br/>From this drop-down menu, select <strong>“statisches Kurvenlicht-Obere Geschwindigkeitsschwelle.”</strong><br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu located toward the bottom<br/>.<br/>In this menu, adjust the value as needed and then confirm. (Default value: 32 km/h) </p>\n<p><em>Note: This is probably a good idea up to a maximum speed of 60 km/h (in urban areas), because otherwise the cornering lights will also be activated on country roads if the steering angle is sufficient.  </em></p>","q2-ga-start-stop-deactivation":"<p><strong>Purpose:</strong> to disable Start and Stop completely.  <br/></p>\n<p><em><strong>Watch out! There are 1 or 2 lines of coding to do here, depending on the method.</strong> <em>(After 2019 deactivation no longer works according to gateway reference “AA”)  </em></em><br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostic socket or OBDeleven box.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program or the OBDeleven application.<br/><br/><strong>Method 1 (voltage method, recommended):</strong></p>\n<p><strong>VCDS :  </strong><br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong> “Limite de tension de départ marche/arrêt” / “Start/Stop voltage limit”</strong>.<br/><br/><strong>6</strong> – On this same page, there is a second drop-down menu, but at the bottom<br/>of the page.<br/>On this menu, select<strong>“12</strong>” (default value = <strong>7.6V</strong>) then validate.<br/></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/vw_start_stop_change_voltage_limit_value-a50bc29b.webp\"/></figure>\n<p><strong><strong>OBDeleven:</strong></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstartstoptension-ec0170bc.webp\"/></figure>\n<p><strong>YouTube video:</strong></p>\n<figure>\n</figure>\n<hr/>\n<p><strong>Method 2 (Temperature method):</strong></p>\n<p><strong>VCDS :</strong> </p>\n<p><strong>Line 1:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Minimaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong>Line 2:</strong></p>\n<p><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“19 – CAN Gateway</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.</p>\n<p><strong>5</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Start/Stopp Auntemperaturvorgabe-Maximaltemperatur</strong>”.</p>\n<p><strong>6</strong> – On this same page, there is a second drop-down menu at the bottom<br/>of the page.<br/>Select<strong>“50</strong>” (default value = <strong>-50.0</strong>) and confirm.</p>\n<p><strong><strong>OBDeleven:</strong></strong></p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/obdelevenstarstoptemp-494422ad.webp\"/></figure>","q2-ga-suppress-belt-alarm":"<p><strong>Purpose:</strong> to suppress the audible alarm and warning light in the Virtual Cockpit when driving without a seatbelt.  <br/><br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select”</strong>, then click on<strong>“17 – Instruments</strong>”.</p>\n<p><strong>4</strong> – Click on<strong>“Coding – 07</strong>” then<strong>“Long Coding Helper</strong>”.</p>\n<p><strong>5</strong> – Select byte <strong>0</strong>:<br/>Bit <strong>2-4</strong>: select <strong>“Seat Belt Warning inactive”</strong> from the drop-down list.</p>\n<p><strong><em>OR</em></strong></p>\n<p><strong>4</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“20103</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“Deactivate</strong> <strong>Seat belt warning”</strong> / <strong>“</strong> <strong>Désactiver l’avertissement de ceinture”.</strong> <br/><br/><strong>7</strong> – On this same page, there is a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select<strong>“Oui</strong>” /<strong>“Yes”</strong> and confirm.</p>\n<figure>\n</figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/8U0_920_940_Module17_Adaptation_desactivate_seat_b-77d3b532.webp\"/></figure>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/voyant_ceinture_de_securite-296648a9.webp\"/></figure>","q2-ga-switch-on-corner-lights-in-reverse":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to activate the Corner Light (AFS) when reversing.</p>\n<p><strong>Procedure:</strong> <br/> 1 – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.</p>\n<p><strong>2</strong> – Switch on the ignition and run the VCDS program.</p>\n<p><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose <strong>“static directional light-bei Rueckwaertsfahrt”</strong> / <strong>“static AFS light-bei Rueckwaertsfahrt”. </strong> </p>\n<p><strong>7</strong> – On this same page, you’ll find a second drop-down menu, at the bottom<br/>of the page.<br/>On this menu, select <em>“<strong>Bilateral</strong>”</em> / <em>“<strong>both sides</strong>”</em>, then confirm.</p>\n<figure><img decoding=\"async\" loading=\"lazy\" src=\"img/IMG_1223-1024x815-9e444f6c.webp\"/></figure>","q2-ga-third-brake-light-on-if-trunk-is-open":"<figure><img alt=\"VAG Coding VCDS ODBeleven Audi Q2 GA\" decoding=\"async\" loading=\"lazy\" src=\"img/AUDI-Q2-GU-80eeeeba.webp\"/></figure>\n<p><strong>Purpose:</strong> to keep the 3rd brake light on if the trunk is not fully closed. For security lighting at night or to make sure your safe is securely closed.  <br/><br/><br/><strong>Warning! There are 2 lines of coding to do here. </strong> <br/><br/><strong>Proceed :</strong> <br/><strong>1</strong> – Engine off, ignition off, connect your official VAG-COM VCDS cable to the computer, then plug the other end into your vehicle’s diagnostics socket.<br/><br/><strong>2</strong> – Switch on the ignition and run the VCDS program.<br/><br/><strong>Line 1:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte22BR MA57-Lichtfunktion C 22</strong>”.<br/><br/><strong>7</strong> – On this same page, there’s a second drop-down menu at the bottom<br/>of the page.<br/>On this, select the value<strong>“Heckdeckel Offen</strong>” and confirm. <em>(Origin: nicht aktiv)</em><br/><br/><br/><strong>Line 2:</strong><br/><br/><strong>3</strong> – Click on<strong>“Select</strong>”, then click on<strong>“09 – Cent. Elect.</strong>”.<br/><br/><strong>4</strong> – Click on<strong>“Security Access – 16</strong>” then enter the code<strong>“31347</strong>”.<br/><br/><strong>5</strong> – Click on<strong>“Adaptation – 10</strong>”.<br/><br/><strong>6</strong> – On this page, at the very top, there is a drop-down menu.<br/>In this drop-down menu, choose<strong>“Leuchte22BR MA57-Dimmwert CD 22</strong>”.<br/><br/><strong>7</strong> – On the same page, you’ll find a second drop-down menu at the bottom<br/>of the page.<br/>On this menu, choose a value between<strong>“0</strong>” and<strong>“100</strong>” depending on the power of the brake light, then confirm. <em>(Origin: 0)</em></p>"};
